import { test, expect } from '@playwright/test';

test.describe('Error Toast Notification', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://your-application-url.com');
  });

  test('should display error toast notification on action failure', async ({ page }) => {
    await page.getByRole('button', { name: 'Trigger Action' }).click();
    const errorToast = page.getByText('Action failed. Please try again.');
    await expect(errorToast).toBeVisible();
  });

  test('should not display error toast notification on successful action', async ({ page }) => {
    await page.getByRole('button', { name: 'Trigger Successful Action' }).click();
    const errorToast = page.getByText('Action failed. Please try again.');
    await expect(errorToast).not.toBeVisible();
  });
});
